INSERT INTO "app_metadata" VALUES('dataset_name','Path Finder Career Recommendation Database');
INSERT INTO "app_metadata" VALUES('version','1.0');
INSERT INTO "app_metadata" VALUES('purpose','Student career exploration and recommendation');
INSERT INTO "app_metadata" VALUES('recommendation_note','Match interests, preferred work style, skills, education and constraints against career profiles. The score is a recommendation aid, not a psychometric diagnosis.');
INSERT INTO "app_metadata" VALUES('recommended_score','interest_match*0.30 + skill_match*0.25 + education_eligibility*0.20 + work_preference*0.10 + domain_preference*0.10 + practical_constraints*0.05');
INSERT INTO "app_metadata" VALUES('important','Keep hard eligibility checks separate from preference matching. Show reasons for every recommendation.');
INSERT INTO "app_metadata" VALUES('salary_policy','Do not hard-code stale salary numbers into recommendation logic. Add verified salary ranges by geography/source/date when available.');
INSERT INTO "app_metadata" VALUES('source_note','NSDC/NOS and NCS are India-focused references. O*NET is a general career-exploration model and should be adapted rather than treated as an India labour-market dataset.');
