INSERT INTO "careers" VALUES(1,'Software Developer',1,'Builds and maintains software applications.','Writing code, testing, debugging, reviewing and deploying applications.',0,'0-5','Office / hybrid',1,1,1,'M.Tech, MCA, certifications, specialization','Senior Developer → Tech Lead → Architect / Engineering Manager','Portfolio and projects are useful for entry.');
INSERT INTO "careers" VALUES(2,'Web Developer',1,'Creates websites and web applications.','Frontend, backend or full-stack development and maintenance.',0,'0-5','Office / hybrid / remote',1,1,1,'Advanced web development, cloud or UX','Developer → Senior Developer → Lead','Practical portfolio matters.');
INSERT INTO "careers" VALUES(3,'Mobile App Developer',1,'Develops Android, iOS or cross-platform mobile applications.','App development, testing, APIs and release management.',0,'0-5','Office / hybrid / remote',1,1,1,'Advanced mobile engineering','Developer → Senior → Mobile Lead','Platform specialization can be added later.');
INSERT INTO "careers" VALUES(4,'DevOps Engineer',1,'Automates software delivery and infrastructure operations.','CI/CD, cloud infrastructure, monitoring and automation.',1,'1-5','Office / hybrid / remote',1,0,1,'Cloud / DevOps specialization','DevOps → Senior → Platform / SRE Lead','Usually easier after development or systems fundamentals.');
INSERT INTO "careers" VALUES(5,'Cloud Engineer',1,'Designs, deploys and supports cloud infrastructure.','Cloud services, networking, IAM, monitoring and automation.',0,'0-5','Office / hybrid / remote',1,1,1,'Cloud certifications / architecture','Cloud Engineer → Senior → Cloud Architect','Hands-on labs are valuable.');
INSERT INTO "careers" VALUES(6,'Data Analyst',2,'Turns data into reports and actionable insights.','SQL, spreadsheets, dashboards, data cleaning and business analysis.',0,'0-5','Office / hybrid',1,1,1,'Advanced analytics / data science','Analyst → Senior Analyst → Analytics Lead','Good entry route for students who enjoy numbers and business.');
INSERT INTO "careers" VALUES(7,'Business Intelligence Analyst',2,'Builds dashboards and business reporting systems.','BI dashboards, SQL, KPIs and stakeholder analysis.',0,'0-5','Office / hybrid',1,1,1,'BI / analytics specialization','BI Analyst → Senior → BI Manager','Business understanding is important.');
INSERT INTO "careers" VALUES(8,'Data Scientist',2,'Uses statistics and machine learning to solve data problems.','Modeling, experimentation, feature engineering and communication.',1,'1-5','Office / hybrid',1,1,1,'M.Tech/MS/advanced data science','Data Scientist → Senior → Lead / Applied Scientist','Strong mathematics and programming help.');
INSERT INTO "careers" VALUES(9,'Machine Learning Engineer',2,'Builds and deploys machine-learning systems.','ML engineering, APIs, pipelines, evaluation and deployment.',1,'1-5','Office / hybrid / remote',1,1,1,'Advanced ML / AI','ML Engineer → Senior → ML Lead / Architect','Usually needs strong programming and ML foundations.');
INSERT INTO "careers" VALUES(10,'AI Engineer',2,'Builds AI-powered products and automation.','AI APIs, ML, LLM applications, evaluation and integration.',0,'0-5','Office / hybrid / remote',1,1,1,'AI specialization / research','AI Engineer → Senior → AI Architect / Lead','Field changes quickly; continuous learning is important.');
INSERT INTO "careers" VALUES(11,'Cybersecurity Analyst',3,'Monitors and investigates security events.','SOC monitoring, incident triage, vulnerability management and reporting.',0,'0-5','Office / hybrid',1,1,1,'Security certifications / specialization','SOC Analyst → Security Analyst → Security Engineer','Networking and Linux fundamentals are useful.');
INSERT INTO "careers" VALUES(12,'Penetration Tester / VAPT Analyst',3,'Tests systems for security weaknesses under authorization.','Security testing, reporting, remediation support and labs.',0,'0-5','Office / hybrid / remote',1,1,1,'Advanced security testing','VAPT Analyst → Senior → Security Consultant','Must work only with authorized systems.');
INSERT INTO "careers" VALUES(13,'Network Engineer',3,'Designs and supports computer networks.','Routing, switching, troubleshooting, network security and monitoring.',0,'0-5','Office / field',0,1,1,'CCNA-level networking / advanced network engineering','Network Engineer → Senior → Network Architect','Hands-on networking labs are useful.');
INSERT INTO "careers" VALUES(14,'Cloud Security Engineer',3,'Secures cloud infrastructure and workloads.','IAM, cloud security controls, monitoring and threat response.',1,'1-5','Office / hybrid / remote',1,0,1,'Cloud/security certifications','Security Engineer → Senior → Cloud Security Architect','Combines cloud and cybersecurity.');
INSERT INTO "careers" VALUES(15,'Product Manager',4,'Coordinates product direction and delivery.','Customer discovery, requirements, prioritization and stakeholder management.',2,'2-10','Office / hybrid',1,1,1,'Product / business specialization','PM → Senior PM → Product Lead / Director','Communication and structured problem solving are important.');
INSERT INTO "careers" VALUES(16,'Project Coordinator / Project Manager',4,'Plans and coordinates projects.','Schedules, risks, budgets, stakeholders and delivery.',0,'0-10','Office / hybrid',1,1,1,'Project management certification','Coordinator → PM → Program Manager','Domain knowledge can be more important than a specific degree.');
INSERT INTO "careers" VALUES(17,'Management Consultant',4,'Analyzes business problems and recommends actions.','Research, analysis, presentations and client work.',0,'0-5','Office / travel / hybrid',1,1,1,'MBA / domain specialization','Analyst → Consultant → Manager / Principal','Strong communication and analytical ability are useful.');
INSERT INTO "careers" VALUES(18,'HR / Talent Acquisition Specialist',4,'Supports hiring and people operations.','Sourcing, interviewing, coordination, HR systems and communication.',0,'0-5','Office / hybrid',1,1,1,'HR specialization / MBA HR','Recruiter → Senior Recruiter → TA Lead / HRBP','People skills are central.');
INSERT INTO "careers" VALUES(19,'Financial Analyst',5,'Analyzes financial information for decisions.','Financial modeling, reporting, valuation and business analysis.',0,'0-5','Office / hybrid',1,1,1,'Finance certifications / advanced finance','Analyst → Senior Analyst → Finance Manager','Excel and financial concepts are important.');
INSERT INTO "careers" VALUES(20,'Accountant',5,'Maintains financial records and supports reporting.','Bookkeeping, reconciliations, tax support and accounting systems.',0,'0-10','Office',0,1,1,'CA/CMA/advanced accounting','Accountant → Senior → Finance Controller','Qualifications vary by role and regulated responsibility.');
INSERT INTO "careers" VALUES(21,'Banking Operations Specialist',5,'Supports banking operations and customer processes.','Transactions, documentation, compliance and customer support.',0,'0-5','Office / branch',0,0,1,'Banking/finance specialization','Operations → Senior → Operations Manager','Bank-specific recruitment rules vary.');
INSERT INTO "careers" VALUES(22,'Risk / Compliance Analyst',5,'Identifies and manages business or regulatory risk.','Controls, documentation, analysis and compliance monitoring.',0,'0-5','Office / hybrid',1,1,1,'Risk/compliance specialization','Analyst → Senior → Risk/Compliance Manager','Accuracy and documentation matter.');
INSERT INTO "careers" VALUES(23,'Digital Marketing Specialist',6,'Plans and executes digital marketing campaigns.','SEO, paid media, analytics, content and social media.',0,'0-5','Office / hybrid / remote',1,1,1,'Performance marketing / analytics','Specialist → Manager → Head of Marketing','Portfolio/campaign projects help.');
INSERT INTO "careers" VALUES(24,'SEO Specialist',6,'Improves search visibility and organic traffic.','Keyword research, technical SEO, content and analytics.',0,'0-5','Office / remote',1,1,1,'Advanced SEO / analytics','SEO Specialist → Senior → SEO Lead','Results-oriented portfolio can help.');
INSERT INTO "careers" VALUES(25,'Sales / Business Development Executive',6,'Finds and develops customer opportunities.','Prospecting, communication, CRM, negotiation and presentations.',0,'0-5','Office / field / hybrid',1,1,1,'Sales specialization / management','BDE → Account Manager → Sales Manager','Compensation may include incentives.');
INSERT INTO "careers" VALUES(26,'Content Writer / Copywriter',6,'Creates written content for audiences and brands.','Research, writing, editing, SEO and communication.',0,'0-5','Remote / office / hybrid',1,1,1,'Content strategy / communications','Writer → Senior → Content Lead','Portfolio is especially important.');
INSERT INTO "careers" VALUES(27,'UI/UX Designer',7,'Designs usable digital interfaces and experiences.','Research, wireframes, prototypes, usability and visual design.',0,'0-5','Office / hybrid / remote',1,1,1,'Product design specialization','Designer → Senior → Design Lead','Portfolio is central.');
INSERT INTO "careers" VALUES(28,'Graphic Designer',7,'Creates visual assets for brands and communications.','Layout, branding, illustration and design tools.',0,'0-5','Office / freelance / hybrid',1,1,1,'Advanced design / branding','Designer → Senior → Art Director','Portfolio is usually more informative than marks alone.');
INSERT INTO "careers" VALUES(29,'Video Editor / Motion Designer',7,'Produces edited video and motion content.','Editing, storytelling, motion graphics and audio workflows.',0,'0-5','Remote / studio / hybrid',1,1,1,'Motion / film specialization','Editor → Senior → Creative Lead','Portfolio and project quality matter.');
INSERT INTO "careers" VALUES(30,'Mechanical Design Engineer',8,'Designs mechanical components and systems.','CAD, drawings, materials, prototyping and engineering analysis.',0,'0-5','Office / manufacturing',0,1,1,'Advanced mechanical design','Engineer → Senior → Design Lead','Engineering degree or relevant technical qualification is common.');
INSERT INTO "careers" VALUES(31,'Electrical Engineer',8,'Designs, tests and maintains electrical systems.','Electrical systems, drawings, testing and maintenance.',0,'0-5','Office / field / plant',0,1,1,'Power/electronics specialization','Engineer → Senior → Engineering Manager','Role requirements vary by industry.');
INSERT INTO "careers" VALUES(32,'Electronics / Embedded Engineer',8,'Builds electronics and embedded systems.','Microcontrollers, embedded C/C++, circuits and testing.',0,'0-5','Lab / office / manufacturing',0,1,1,'Embedded / electronics specialization','Engineer → Senior → Embedded Lead','Projects can demonstrate practical ability.');
INSERT INTO "careers" VALUES(33,'Production / Manufacturing Engineer',8,'Improves manufacturing processes and output.','Production planning, quality, process improvement and safety.',0,'0-5','Plant / manufacturing',0,1,1,'Industrial engineering / operations','Engineer → Senior → Plant / Operations Manager','Work is often site-based.');
INSERT INTO "careers" VALUES(34,'Civil / Site Engineer',9,'Supports construction and infrastructure projects.','Site supervision, drawings, estimation, safety and coordination.',0,'0-5','Field / site / office',0,1,1,'Construction management','Site Engineer → Senior → Project Manager','Site work can be a significant part of the role.');
INSERT INTO "careers" VALUES(35,'Quantity Surveyor / Cost Estimator',9,'Estimates project quantities and costs.','BOQ, estimation, contracts and cost control.',0,'0-5','Office / site',0,1,1,'Quantity surveying / contracts','Estimator → Senior → Cost Manager','Attention to detail is important.');
INSERT INTO "careers" VALUES(36,'Healthcare Administrator',10,'Coordinates healthcare facility operations.','Scheduling, documentation, coordination and service operations.',0,'0-5','Hospital / office',0,1,1,'Healthcare management','Coordinator → Manager → Hospital Operations','Clinical qualification is not necessarily required for administrative roles.');
INSERT INTO "careers" VALUES(37,'Medical Laboratory Technician',10,'Performs laboratory procedures and supports diagnostics.','Sample handling, laboratory procedures, documentation and safety.',0,'0-5','Laboratory / hospital',0,1,1,'Relevant healthcare/lab qualification','Technician → Senior → Lab Supervisor','Specific qualifications may be regulated.');
INSERT INTO "careers" VALUES(38,'Pharmacy Professional',10,'Supports safe dispensing and pharmacy operations.','Medication knowledge, dispensing, records and patient communication.',0,'0-5','Pharmacy / hospital',0,1,1,'Relevant pharmacy qualification','Pharmacist → Senior → Pharmacy Manager','Professional registration requirements may apply.');
INSERT INTO "careers" VALUES(39,'Teacher / Subject Educator',11,'Teaches students and supports learning.','Lesson planning, teaching, assessment and communication.',0,'0-10','School / classroom / hybrid',0,1,1,'Teacher education / subject specialization','Teacher → Senior Teacher → Coordinator / Principal','Eligibility varies by level and institution.');
INSERT INTO "careers" VALUES(40,'Corporate Trainer',11,'Delivers training and learning programs.','Presentation, curriculum design, facilitation and assessment.',0,'0-10','Office / travel / hybrid',1,1,1,'Learning & development specialization','Trainer → Senior Trainer → L&D Manager','Domain expertise plus communication is useful.');
INSERT INTO "careers" VALUES(41,'Government / Administrative Services',12,'Supports public administration and government programs.','Administration, documentation, public service and policy implementation.',0,'0-10','Office / field',0,0,1,'Relevant competitive exam / qualification','Entry role → Senior → Administrative leadership','Recruitment and eligibility depend on the specific service/exam.');
INSERT INTO "careers" VALUES(42,'Legal Assistant / Paralegal',12,'Supports legal research, documentation and case preparation.','Legal research, drafting support, records and coordination.',0,'0-5','Office / court / hybrid',1,1,1,'Law specialization','Assistant → Paralegal / Legal Executive → Senior','Regulated legal practice requires appropriate qualification.');
INSERT INTO "careers" VALUES(43,'Agriculture / Agritech Specialist',13,'Applies agriculture knowledge to production, technology or services.','Crop systems, field data, agritech tools and advisory work.',0,'0-5','Field / office / hybrid',1,1,1,'Agriculture specialization','Specialist → Senior → Agritech / Farm Operations Lead','Opportunity types vary widely by region.');
INSERT INTO "careers" VALUES(44,'Environmental / Sustainability Analyst',13,'Supports environmental assessment and sustainability programs.','Data, reporting, environmental standards and project support.',0,'0-5','Office / field / hybrid',1,1,1,'Environmental science / sustainability','Analyst → Senior → Sustainability Manager','Technical requirements vary by role.');
INSERT INTO "careers" VALUES(45,'Hotel Operations Executive',14,'Coordinates guest and hotel operations.','Guest service, reservations, operations and team coordination.',0,'0-5','Hotel / field',0,1,1,'Hospitality management','Executive → Supervisor → Operations Manager','Shift work may be required.');
INSERT INTO "careers" VALUES(46,'Travel / Tourism Coordinator',14,'Plans and coordinates travel services.','Itineraries, customer service, bookings and supplier coordination.',0,'0-5','Office / hybrid / field',1,1,1,'Tourism / travel specialization','Coordinator → Senior → Travel Operations Manager','Language skills can be useful.');
INSERT INTO "careers" VALUES(47,'Supply Chain Analyst',15,'Analyzes supply-chain performance and planning.','Excel/SQL, inventory, logistics, KPIs and forecasting.',0,'0-5','Office / hybrid',1,1,1,'Supply chain / analytics','Analyst → Senior → Supply Chain Manager','Analytical and operational skills combine well.');
INSERT INTO "careers" VALUES(48,'Procurement Executive',15,'Sources goods/services and manages supplier processes.','Vendor management, negotiation, purchase orders and analysis.',0,'0-5','Office / hybrid',1,1,1,'Procurement / supply chain','Executive → Senior → Procurement Manager','Negotiation and documentation are important.');
INSERT INTO "careers" VALUES(49,'Automotive Technician',16,'Diagnoses, repairs and maintains vehicles.','Diagnostics, mechanical systems, electrical systems and repair.',0,'0-10','Workshop / field',0,1,1,'Automotive certifications','Technician → Senior → Workshop Supervisor / Owner','Hands-on practical ability is central.');
INSERT INTO "careers" VALUES(50,'Electrician / Electrical Technician',16,'Installs, maintains and repairs electrical systems.','Wiring, testing, maintenance and safety.',0,'0-10','Field / site / workshop',0,1,1,'ITI / relevant technical qualification','Technician → Senior → Contractor / Supervisor','Licensing and local requirements can apply.');
INSERT INTO "careers" VALUES(51,'Plumber / Plumbing Technician',16,'Installs and repairs plumbing systems.','Pipework, fixtures, maintenance and fault diagnosis.',0,'0-10','Field / construction',0,1,1,'ITI / relevant technical qualification','Technician → Contractor / Business Owner','Local licensing may apply.');
INSERT INTO "careers" VALUES(52,'Food Production / Quality Technician',16,'Supports food production and quality processes.','Production, hygiene, documentation and quality checks.',0,'0-5','Plant / laboratory',0,1,1,'Food technology / relevant technical training','Technician → Quality Executive → QA Manager','Industry-specific standards may apply.');
