BEGIN TRANSACTION;
CREATE TABLE app_metadata (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE career_domains (
    career_id INTEGER,
    domain_id INTEGER,
    relevance REAL DEFAULT 1.0,
    PRIMARY KEY(career_id, domain_id),
    FOREIGN KEY(career_id) REFERENCES careers(career_id),
    FOREIGN KEY(domain_id) REFERENCES domains(domain_id)
);
CREATE TABLE career_education (
    career_id INTEGER,
    education_level TEXT,
    degree_or_stream TEXT,
    importance TEXT DEFAULT 'eligible',
    FOREIGN KEY(career_id) REFERENCES careers(career_id)
);
CREATE TABLE career_interests (
    career_id INTEGER,
    interest_id INTEGER,
    weight REAL DEFAULT 1.0,
    PRIMARY KEY(career_id, interest_id),
    FOREIGN KEY(career_id) REFERENCES careers(career_id),
    FOREIGN KEY(interest_id) REFERENCES interests(interest_id)
);
CREATE TABLE career_opportunities (
    opportunity_id INTEGER PRIMARY KEY,
    career_id INTEGER NOT NULL,
    role_name TEXT NOT NULL,
    seniority TEXT,
    industry TEXT,
    opportunity_type TEXT,
    typical_experience TEXT,
    work_mode TEXT,
    description TEXT,
    FOREIGN KEY(career_id) REFERENCES careers(career_id)
);
CREATE TABLE career_skills (
    career_id INTEGER,
    skill_id INTEGER,
    importance TEXT DEFAULT 'preferred',
    weight REAL DEFAULT 1.0,
    FOREIGN KEY(career_id) REFERENCES careers(career_id),
    FOREIGN KEY(skill_id) REFERENCES skills(skill_id),
    PRIMARY KEY(career_id, skill_id)
);
CREATE TABLE career_sources (
    source_id INTEGER PRIMARY KEY,
    career_id INTEGER,
    source_name TEXT NOT NULL,
    source_url TEXT NOT NULL,
    source_type TEXT,
    accessed_on TEXT,
    note TEXT,
    FOREIGN KEY(career_id) REFERENCES careers(career_id)
);
CREATE TABLE careers (
    career_id INTEGER PRIMARY KEY,
    career_name TEXT UNIQUE NOT NULL,
    domain_id INTEGER NOT NULL,
    description TEXT,
    typical_work TEXT,
    entry_level INTEGER DEFAULT 0,
    max_experience_band TEXT,
    work_environment TEXT,
    remote_possible INTEGER DEFAULT 0,
    entrepreneurship_possible INTEGER DEFAULT 0,
    public_sector_possible INTEGER DEFAULT 0,
    higher_study_path TEXT,
    advancement_path TEXT,
    notes TEXT,
    FOREIGN KEY(domain_id) REFERENCES domains(domain_id)
);
CREATE TABLE domains (
    domain_id INTEGER PRIMARY KEY,
    domain_name TEXT UNIQUE NOT NULL,
    description TEXT
);
CREATE TABLE education_options (
    education_id INTEGER PRIMARY KEY,
    education_level TEXT NOT NULL,
    degree_or_stream TEXT,
    description TEXT
);
CREATE TABLE interests (
    interest_id INTEGER PRIMARY KEY,
    code TEXT UNIQUE NOT NULL,
    interest_name TEXT UNIQUE NOT NULL,
    description TEXT
);
CREATE TABLE recommendation_options (
    option_id INTEGER PRIMARY KEY,
    question_id INTEGER NOT NULL,
    option_key TEXT NOT NULL,
    option_text TEXT NOT NULL,
    interest_id INTEGER,
    skill_id INTEGER,
    domain_id INTEGER,
    FOREIGN KEY(question_id) REFERENCES recommendation_questions(question_id),
    FOREIGN KEY(interest_id) REFERENCES interests(interest_id),
    FOREIGN KEY(skill_id) REFERENCES skills(skill_id),
    FOREIGN KEY(domain_id) REFERENCES domains(domain_id)
);
CREATE TABLE recommendation_questions (
    question_id INTEGER PRIMARY KEY,
    question_key TEXT UNIQUE NOT NULL,
    question_text TEXT NOT NULL,
    answer_type TEXT NOT NULL,
    weight REAL DEFAULT 1.0
);
CREATE TABLE skills (
    skill_id INTEGER PRIMARY KEY,
    skill_name TEXT UNIQUE NOT NULL,
    skill_type TEXT NOT NULL,
    category TEXT
);
CREATE TABLE students (
    student_id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT,
    age INTEGER,
    location TEXT,
    education_level TEXT,
    degree TEXT,
    specialization TEXT,
    experience_years REAL DEFAULT 0,
    preferred_work_mode TEXT,
    preferred_location_type TEXT,
    salary_expectation_min INTEGER,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_careers_domain ON careers(domain_id);
CREATE INDEX idx_career_skills_skill ON career_skills(skill_id);
CREATE INDEX idx_career_interests_interest ON career_interests(interest_id);
CREATE INDEX idx_opportunities_career ON career_opportunities(career_id);
DELETE FROM "sqlite_sequence";
COMMIT;
